OJA_ROME.add("B1615",{"code":"B1615","t":"Orfèvre tourneur repousseur / Orfèvre tourneuse repousseuse","dom":"Métal, verre, bijouterie et horlogerie","a":["Tourneur-repousseur / Tourneuse-repousseuse en orfèvrerie"],"d":"Le tourneur repousseur en orfèvrerie assure la réalisation de pièces en utilisant un tour à repousser, son expertise lui garantit une méthodologie adaptée à toutes les pièces et à l'assemblage de forme simple ou complexe. Dispose d'une maitrise technique pour la déformation et le lissage des matières Procède aux réalisations des outillages nécessaire pour la transformation des métaux ","acc":"Ce métier est accessible avec un diplôme de niveau CAP à Bac. Il est également accessible avec une expérience professionnelle sans diplôme particulier avec des compétences appréciées pour le contenu de l'activité. ","sf":[["Communication, Multimédia","Réaliser des dessins ou plans des pièces et des outils à réaliser",490230,1],["Data et Nouvelles technologies","Analyser la fiche de fabrication du produit pour répondre aux attentes du client (gamme du produit, niveau de finition attendu, délais de production prévus...)",405130,1],["Data et Nouvelles technologies","Utiliser une interface graphique (tablette, smartphone, machine à commande numérique etc.)",400834,0],["Production, Fabrication","Définir les étapes d'intervention pour le façonnage ou la décoration d'un objet",125156,0],["Production, Fabrication","Reprendre les défauts d'une pièce en ajustage, débosselage ou polissage",490240,1],["Production, Fabrication","Réaliser des pièces d'orfèvrerie spécifiques avec des instructions données ou en autonomie",490207,1],["Aménagement","Organiser son espace et son poste de travail, dans les règles de propreté et de sécurité",490239,1],["Maintenance, Réparation","Assurer la maintenance de premier niveau de ses outils de travail",402267,0],["Prévention des risques","Mettre en place une gestion préventive des risques professionnels",121224,0],["Qualité","Contrôler la qualité et s'assurer des ajustages des états de surface",490233,1],["Qualité","Contrôler les finitions",490238,0],["Qualité","Détecter les défauts restants, les nuances à polir et les contraintes d'ajustement",490236,1],["Communication","Effectuer une transmission d'information à son responsable",490052,1],["Communication","Favoriser l'entente, la collaboration",300468,0],["Organisation","Appliquer les règles de sécurité dans les pratiques et les tâches",490205,0],["Organisation","Identifier les caractéristiques du produit afin de mobiliser les meilleures techniques possibles de préparation ou de montage",405129,1],["Organisation","Respecter les règles et consignes de rangement et de nettoyage de son poste de travail",405079,1],["Développement des compétences","Mobiliser sa concentration tout au long d'un processus",405056,0]],"se":[["Faire preuve d'autonomie",300460],["Faire preuve de persévérance",300485],["Faire preuve de rigueur et de précision",300490]],"sv":[["Domaines d'expertise","Histoire de l'art",119191,0],["Domaines d'expertise","Connaissance des différents alliages et de l'argent massif",490215,0],["Domaines d'expertise","Connaissance des poinçons pour l'orfèvrerie et la bijouterie",490213,0],["Techniques professionnelles","Techniques fondamentales de la transformation des matériaux",490241,0],["Techniques professionnelles","Techniques fondamentales d'orfèvrerie sur les matériaux",489710,0]],"cert":[["BMA Orfèvrerie options Monture-tournure et Gravure-ciselure",490059],["CAP Orfèvre option B : tourneur repousseur en orfèvrerie",490202],["CAP art et techniques de la bijouterie-joaillerie option bijouterie-joaillerie",404986]],"ctx":[["Statut d'emploi","Salarié secteur privé (CDI, CDD)",403103],["Conditions de travail et risques professionnels","En atelier",403092],["Conditions de travail et risques professionnels","Manipulation d'un engin, équipement ou outil dangereux",300794],["Horaires et durée du travail","Travail en journée",300806]]});
